import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../providers/task_store.dart';
class StatisticsScreen extends StatelessWidget{const StatisticsScreen({super.key});@override Widget build(BuildContext context){final s=context.watch<TaskStore>();final total=s.tasks.length;final overdue=s.overdue.length;final high=s.tasks.where((t)=>t.priority==2).length;final med=s.tasks.where((t)=>t.priority==1).length;final low=s.tasks.where((t)=>t.priority==0).length;return Scaffold(appBar:AppBar(title:const Text('الإحصائيات',style:TextStyle(fontWeight:FontWeight.bold))),body:ListView(padding:const EdgeInsets.all(18),children:[GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,childAspectRatio:1.65,crossAxisSpacing:10,mainAxisSpacing:10,children:[_metric(context,'إجمالي المهام',total,Icons.checklist),_metric(context,'مكتملة',s.doneCount,Icons.task_alt),_metric(context,'غير مكتملة',s.openCount,Icons.pending_actions),_metric(context,'متأخرة',overdue,Icons.warning_amber_rounded)]),const SizedBox(height:24),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('نسبة الإنجاز',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:18),SizedBox(height:150,child:Center(child:SizedBox(width:145,height:145,child:Stack(alignment:Alignment.center,children:[SizedBox(width:130,height:130,child:CircularProgressIndicator(value:s.progress,strokeWidth:14,backgroundColor:Theme.of(context).colorScheme.surfaceContainerHighest)),Column(mainAxisSize:MainAxisSize.min,children:[Text('${(s.progress*100).round()}%',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),const Text('إنجاز')])])))),Text('مكتملة: ${s.doneCount}  •  متبقية: ${s.openCount}')]))),const SizedBox(height:16),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('حسب الأولوية',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:14),_bar(context,'مرتفعة',high,total,Colors.red),_bar(context,'متوسطة',med,total,Colors.orange),_bar(context,'منخفضة',low,total,Colors.green)]))),const SizedBox(height:16),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('الفئات',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),...{for(final t in s.tasks)t.category}.map((cat){final count=s.tasks.where((t)=>t.category==cat).length;return ListTile(contentPadding:EdgeInsets.zero,title:Text(cat),trailing:Text('$count'));}),if(total==0)const Text('ستظهر الإحصائيات هنا بعد إضافة المهام.')])))]));}
 Widget _metric(BuildContext c,String label,int n,IconData icon)=>Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Icon(icon,color:Theme.of(c).colorScheme.primary),Text('$n',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),Text(label)])));
 Widget _bar(BuildContext c,String label,int n,int total,Color color)=>Padding(padding:const EdgeInsets.symmetric(vertical:7),child:Column(children:[Row(children:[Expanded(child:Text(label)),Text('$n')]),const SizedBox(height:5),ClipRRect(borderRadius:BorderRadius.circular(10),child:LinearProgressIndicator(value:total==0?0:n/total,minHeight:8,color:color))]));
}
